import{z as c,x as p,o,c as d,q as r,j as E,D as n,d as e,s as l,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"CSP","description":"","frontmatter":{"title":"CSP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csp.md","filePath":"cs/csp.md","lastUpdated":1791063341000}'),A={name:"cs/csp.md"};function B(C,a,S,u,h,m){const s=p("Mermaid");return o(),d("div",null,[a[2]||(a[2]=r('<h1 id="csp" tabindex="-1">CSP <a class="header-anchor" href="#csp" aria-label="Permalink to &quot;CSP&quot;">​</a></h1><div class="epigraph"><p>内容安全策略用声明限制页面能加载和执行的脚本、框架与连接。它把「不小心拼进页面的字符串」从默认可执行改成默认拒绝，是 XSS 的纵深，不是许可再拼接。</p><footer>—— W3C CSP；Stamm, Sterne and Markham；对照 MDN 对指令的整理</footer></div><p>上一课<a href="/cs/xss">XSS</a>的根治是输出编码，但编码要求每处拼接都做对。缺口是<strong>即使漏了一处</strong>，浏览器策略仍能挡住内联脚本的执行。本课讲 CSP 指令，不写绕过清单。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器默认允许内联脚本与 eval，XSS 一次注入即可执行。CSP 把默认翻成拒绝：script-src 用每响应随机的 nonce 或脚本内容 hash 放行自己的一等脚本，其余一律不跑。缺口是部署——策略怎么写，report-only 模式怎么先观测违例再收紧。</p><h3 id="nonce-要随机" tabindex="-1">nonce 要随机 <a class="header-anchor" href="#nonce-要随机" aria-label="Permalink to &quot;nonce 要随机&quot;">​</a></h3><p>nonce 必须随机：固定 nonce 等于没策略，注入脚本只要读一次页面就拿到通行证；每个响应用 CSPRNG 现生成。</p><p><span class="marginnote">nonce 就是&quot;一次性通行口令&quot;：服务端每生成一次页面，用随机数现造一个新字符串，策略头和 <code>&lt;script nonce=...&gt;</code> 标签各写一份。浏览器只认当轮匹配的；攻击者此刻抄到的口令，下一轮就作废。</span></p><p><span class="marginnote">CSP Level 3。unsafe-inline 几乎撤销脚本保护。本课禁止绕过教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法先列关键指令：script-src 管脚本，default-src 给其余资源兜底，frame-ancestors 管本页能被谁嵌框，connect-src 管脚本能往哪发请求。对照下一课 CORS：CSP 管本页能拉什么，CORS 管外源能不能读响应，两扇门方向相反。</p><p><span class="marginnote">Report-Only 模式等于&quot;只报警不执法&quot;：违例照常上报但脚本照跑。先观测一段时间、确认没误杀自家脚本，再把同一份策略切成强制执行；一上来就强制，一旦误杀，页面可能整个瘫掉。</span></p>',13)),(o(),E(i,null,{default:n(()=>[l(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAGE%5B%22%E9%A1%B5%E9%9D%A2%22%5D%20--%3E%20POL%5B%22CSP%20%E5%A3%B0%E6%98%8E%22%5D%0A%20%20POL%20--%3E%20DENY%5B%22%E6%8B%92%E7%BB%9D%E6%9C%AA%E6%8E%88%E6%9D%83%E8%84%9A%E6%9C%AC%22%5D%0A%20%20POL%20--%3E%20RPT%5B%22%E6%8A%A5%E5%91%8A%E8%BF%9D%E4%BE%8B%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("机制是纵深：编码漏掉的那一处，注入的 "),t("code",null,"<script>"),e(" 因缺 nonce 被浏览器拒绝执行——错误被限制在「注入了死文本」而非「代码执行」。它不挡无脚本的 HTML 注入：假表单、外观篡改这类钓鱼仍在。一旦写进 unsafe-inline，脚本保护几乎整体撤销。CORS 下一课是读响应的另一扇门。")],-1)),(o(),E(i,null,{default:n(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E6%94%B6%E5%88%B0%E5%93%8D%E5%BA%94%22%5D%20--%3E%20C%7B%22script%20%E5%B8%A6%E5%BD%93%E8%BD%AE%E5%90%88%E6%B3%95%20nonce%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20RUN%5B%22%E6%89%A7%E8%A1%8C%E4%B8%80%E7%AD%89%E8%84%9A%E6%9C%AC%22%5D%0A%20%20C%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E6%B3%A8%E5%85%A5%E7%9A%84%E8%A3%B8%E6%A0%87%E7%AD%BE%22%7C%20BLK%5B%22%E6%8B%92%E7%BB%9D%E6%89%A7%E8%A1%8C%E5%B9%B6%E6%8A%A5%E8%BF%9D%E4%BE%8B%22%5D%0A%20%20BLK%20--%3E%20EFF%5B%22%E6%B3%A8%E5%85%A5%E9%80%80%E5%8C%96%E4%B8%BA%E6%AD%BB%E6%96%87%E6%9C%AC%22%5D%0A%20%20RUN%20--%3E%20CON%5B%22%E5%A4%96%E5%8F%91%E8%AF%B7%E6%B1%82%E5%8F%A6%E5%8F%97%20connect-src%20%E9%99%90%E5%88%B6%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">初学者容易以为&quot;上了 CSP 就可以不做输出编码&quot;。实际关系是纵深：编码失守时，CSP 把损失从&quot;任意代码执行&quot;压到&quot;一段死文本&quot;，但假表单这类不带脚本的注入它照旧管不住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写绕过；边界要点名：策略的安全性按最松的一处计算——任何宽域名通配或放行 data: URL 都拉低整体。CORS 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>XSS 根治是编码；CSP 是浏览器默认拒绝。</li><li>nonce/hash 放行自己的脚本。</li><li>unsafe-inline 撤防。</li><li>下一课 CORS。</li><li>出处：W3C CSP；Stamm, Sterne and Markham。</li></ul>',5))])}const f=c(A,[["render",B]]);export{D as __pageData,f as default};
